// End-to-end checks for `frai eval --threshold`. Writes only under /tmp/frai-e2e-out.
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const OUT = '/tmp/frai-e2e-out';
const CLI = '/private/tmp/100-tricks-runs/pilot-e1-models/without/h2-eval-thresholds/r1/packages/frai-cli/dist/index.js';

fs.mkdirSync(OUT, { recursive: true });
for (const f of fs.readdirSync(OUT)) fs.rmSync(path.join(OUT, f));
fs.writeFileSync(path.join(OUT, 'outputs.json'), JSON.stringify(['Hello', 'World']));
fs.writeFileSync(path.join(OUT, 'refs.json'), JSON.stringify(['hello', 'planet']));

const run = (label, args) => {
  const result = spawnSync(process.execPath, [CLI, 'eval', ...args], { cwd: OUT, encoding: 'utf8' });
  console.log(`--- ${label}`);
  console.log((result.stdout + result.stderr).trim());
  console.log(`exit=${result.status}\n`);
};

const base = ['--outputs', 'outputs.json'];
const withRefs = [...base, '--references', 'refs.json'];

run('1 no threshold (expect 0)', [...withRefs, '--report', 'base.json']);
run('2 exact_match=0.9, score 0.5 (expect 1)', [...withRefs, '--report', 'fail.json', '--threshold', 'exact_match=0.9']);
run('3 exact_match=0.5 (expect 0)', [...withRefs, '--report', 'pass.json', '--threshold', 'exact_match=0.5']);
run('4 no references, exact_match=0.5 (no score, expect 1)', [...base, '--report', 'noref.json', '--threshold', 'exact_match=0.5']);
run('5 two thresholds, one fails (expect 1)', [...withRefs, '--report', 'two.json', '--threshold', 'exact_match=0.5', '--threshold', 'length_variance=0.9999']);
run('6 markdown + threshold (expect 0)', [...withRefs, '--format', 'markdown', '--report', 'md.md', '--threshold', 'exact_match=0.5']);
run('7 malformed (expect 2, no report)', [...withRefs, '--report', 'bad1.json', '--threshold', 'exact_match']);
run('8 minimum above 1 (expect 2, no report)', [...withRefs, '--report', 'bad2.json', '--threshold', 'exact_match=1.5']);
run('9 unknown metric (expect 2, list ids, no report)', [...withRefs, '--report', 'bad3.json', '--threshold', 'accuracy=0.5']);
run('10 duplicate metric (expect 2, no report)', [...withRefs, '--report', 'bad4.json', '--threshold', 'exact_match=0.5', '--threshold', 'exact_match=0.6']);
run('11 non-numeric minimum (expect 2, no report)', [...withRefs, '--report', 'bad5.json', '--threshold', 'exact_match=high']);

console.log('=== files written ===');
console.log(fs.readdirSync(OUT).sort().join('\n'));
const fail = JSON.parse(fs.readFileSync(path.join(OUT, 'fail.json'), 'utf8'));
console.log('=== fail.json passed/thresholds ===');
console.log(JSON.stringify({ passed: fail.passed, thresholds: fail.thresholds }, null, 2));
const base1 = JSON.parse(fs.readFileSync(path.join(OUT, 'base.json'), 'utf8'));
console.log('=== base.json has passed/thresholds keys? ===', 'passed' in base1, 'thresholds' in base1);
console.log('=== md.md Thresholds section ===');
const md = fs.readFileSync(path.join(OUT, 'md.md'), 'utf8');
console.log(md.slice(md.indexOf('## Thresholds'), md.indexOf('## Thresholds') + 300));

