+    if (!specs.length)
+        return undefined;
+    const thresholds = {};
+    specs.forEach((spec) => {
+        const parts = spec.split('=');
+        const metric = (parts[0] ?? '').trim();
+        const value = (parts[1] ?? '').trim();
+        if (parts.length !== 2 || !metric) {
+            throw new UsageError(`Invalid --threshold "${spec}": expected <metric>=<min>, for example exact_match=0.9.`);
+        }
+        if (!/^(\d+(\.\d+)?|\.\d+)$/.test(value) || Number(value) > 1) {
+            throw new UsageError(`Invalid --threshold "${spec}": minimum must be a number between 0 and 1.`);
